def generate_pascal_triangle(n: int, mod: int = 1_000_000_007) -> list[list[int]]:
    C = [[0] * (i + 1) for i in range(n + 1)]
    for i in range(n + 1):
        C[i][0] = C[i][i] = 1
        for j in range(1, i):
            C[i][j] = (C[i - 1][j] + C[i - 1][j - 1]) % mod
    return C

